import sys, os, base64, json, time, uuid, glob
sys.path.insert(0, '/data/scripts')
from upload_router import detect_format, hint_format, WEAK_FORMATS, zip_encryption

def _reject(message, fmt=''):
    # Blocking failure: reported in the ack AND routed to the switch's dead-end
    # so the parse pipeline never runs on bytes we know are unusable.
    return [{'json': {
        'file_path': '', 'filename': filename or 'upload', 'detected_format': fmt,
        'sketch_id': sketch_id, 'size': 0, 'context': context,
        'accepted': False, 'errors': [message], 'error': message,
    }}]

item = _items[0] if _items else {}
_j = item.get('json', {}) if isinstance(item.get('json'), dict) else {}
# n8n webhook v2 nests the POST body under item.json.body - read that, with fallback.
body = _j.get('body', _j) if isinstance(_j.get('body'), dict) else _j
binary = item.get('binary') if isinstance(item, dict) else None

filename = body.get('filename', '')
sketch_id = body.get('sketch_id', '')
fmt = body.get('type', '')
# Analyst's description of the payload, from the Ingest tab's Context field.
context = str(body.get('context') or '')[:2000]
raw_bytes = b''

# A chunked upload arrives as a staged id, not as bytes. The file is already
# on the shared staging mount. Resolve it, classify from the central directory
# or a bounded header, and hand the path to the parser. Do not copy it into
# /tmp and do not put the bytes on this item.
# SPOTTER_INGEST_STAGING_DIR and SPOTTER_RUNNER_PARSE_MAX_BYTES are read here
# so a value set only on the n8n service (or missing from the runner allowlist)
# cannot silently fall back. ingest_staging reads the same names.
staged_id = str(body.get('staged_id') or '').strip()
if staged_id:
    os.environ.get('SPOTTER_INGEST_STAGING_DIR', '/data/ingest-staging')
    _runner_cap = int(os.environ.get('SPOTTER_RUNNER_PARSE_MAX_BYTES', str(1024 ** 3)))
    from ingest_staging import resolve_staged, host_command, StagingError
    from upload_router import detect_format_path, zip_encryption_path
    try:
        staged = resolve_staged(staged_id)
    except StagingError as _se:
        return _reject(str(_se), 'staged')
    filename = filename or staged.get('filename') or 'upload'
    file_path = staged['path']
    size = int(staged.get('size') or 0)
    _enc, _total = zip_encryption_path(file_path)
    fmt = detect_format_path(file_path, filename, max_read=_runner_cap)
    if context and fmt in WEAK_FORMATS:
        _fd = os.open(file_path, os.O_RDONLY)
        try:
            _head = os.read(_fd, 1024 * 1024)
        finally:
            os.close(_fd)
        fmt = hint_format(context, _head, fmt)
    if _total and _enc == _total:
        return _reject(
            f'archive is password-protected: all {_total} files inside are encrypted, '
            f'so nothing could be read. Detected as {fmt!r} from the member names '
            f'only. Re-upload the output zipped WITHOUT a password.',
            fmt)
    if size > _runner_cap:
        return _reject(
            f'{filename} ({size} bytes) is on disk at {file_path} but is over the '
            f'{_runner_cap} byte in-runner parse cap, so it was not read. '
            f'Ingest it on the host: {host_command(fmt, file_path)}',
            fmt or 'oversize')
    return [{'json': {
        'file_path': file_path,
        'filename': filename,
        'detected_format': fmt,
        'sketch_id': sketch_id,
        'size': size,
        'context': context,
        'accepted': True,
        'staged': True,
        'errors': ([f'{_enc} of {_total} files in this archive are password-protected '
                    f'and were skipped'] if _enc else []),
    }}]


# Which explicit payload field the caller used, if any. The webhook runs with
# rawBody: true, so item.binary is populated on EVERY request -- for a plain JSON
# POST it holds the request envelope itself. Resolving binary first therefore
# hijacked every csv_text / text (paste) upload and wrote the ~150-byte JSON
# envelope as though it were the uploaded file, which then "ingested" as generic
# JSON and produced nothing. Explicit fields are checked first; binary is the
# multipart-upload fallback. An explicit field that carries no bytes is an error,
# never a reason to fall back to the envelope.
_payload_field = ''
for _k in ('zip_b64', 'csv_text', 'text', 'data'):
    if _k in body:
        _payload_field = _k
        break

MAX_UPLOAD_BYTES = int(os.environ.get('SPOTTER_UPLOAD_MAX_BYTES', str(32 * 1024 * 1024)))

def _read_n8n_fs(bin_id):
    # bin_id: 'filesystem-v2:workflows/WF/executions/temp/binary_data/UUID'
    if not (isinstance(bin_id, str) and bin_id.startswith('filesystem-v2:')):
        return b''
    rel = bin_id[len('filesystem-v2:'):]
    fpath = '/home/node/.n8n/storage/' + rel
    try:
        sz = os.path.getsize(fpath)
        fd = os.open(fpath, os.O_RDONLY)
        data = os.read(fd, sz)
        os.close(fd)
        return data
    except Exception:
        return b''

if _payload_field == 'zip_b64':
    try:
        raw_bytes = base64.b64decode(body['zip_b64'] or '')
    except Exception as e:
        return _reject(f'base64 decode failed: {e}', fmt)
elif _payload_field in ('csv_text', 'text'):
    raw_bytes = (body.get(_payload_field) or '').encode()
    filename = filename or 'paste.txt'
elif _payload_field == 'data':
    d = body['data']
    raw_bytes = json.dumps(d).encode() if isinstance(d, (dict, list)) else str(d).encode()
elif binary:
    # binary: {'file': {'mimeType':..,'data':'filesystem-v2','id':'filesystem-v2:..','fileName':..}}
    bin_obj = None
    if isinstance(binary, dict):
        if 'mimeType' in binary or ('data' in binary and 'id' in binary):
            bin_obj = binary  # flat (older n8n)
        else:
            for v in binary.values():
                if isinstance(v, dict):
                    bin_obj = v
                    break
    if isinstance(bin_obj, dict):
        if not filename:
            filename = bin_obj.get('fileName', '') or bin_obj.get('name', '')
        data_val = bin_obj.get('data', '')
        bin_id = bin_obj.get('id', '')
        if data_val and data_val != 'filesystem-v2' and not data_val.startswith('filesystem-v2:'):
            try:
                pad = (4 - len(data_val) % 4) % 4
                raw_bytes = base64.b64decode(data_val + '=' * pad)
            except Exception:
                raw_bytes = b''
        else:
            raw_bytes = _read_n8n_fs(bin_id)

# An explicit payload field that produced nothing is a failed upload, not an
# empty one: report it instead of continuing into a 0-entity "success".
if _payload_field and not raw_bytes:
    return _reject(
        f"upload field '{_payload_field}' was present but carried no data",
        'empty')

if raw_bytes and len(raw_bytes) > MAX_UPLOAD_BYTES:
    return _reject(
        f'upload too large ({len(raw_bytes)} bytes > {MAX_UPLOAD_BYTES})',
        fmt or 'oversize')

if not fmt and raw_bytes:
    fmt = detect_format(raw_bytes, filename)

# Bytes beat prose. Only the weak verdicts (text / json / zip_unknown) are open to
# the analyst's context, and hint_format still requires the payload to corroborate
# the hint -- so "process list" typed above an nmap paste stays nmap.
if raw_bytes and context and fmt in WEAK_FORMATS:
    fmt = hint_format(context, raw_bytes, fmt)

# A password-protected archive parses to zero nodes no matter which format it
# was detected as. Catch it before the pipeline runs, while the ack can still
# report it -- see zip_encryption() in upload_router.
_enc, _total = zip_encryption(raw_bytes) if raw_bytes else (0, 0)
if _total and _enc == _total:
    return _reject(
        f'archive is password-protected: all {_total} files inside are encrypted, '
        f'so nothing could be read. Detected as {fmt!r} from the member names '
        f'only. Re-upload the output zipped WITHOUT a password.',
        fmt)

# Persist bytes to the shared drop mount and pass only the PATH downstream.
# Multi-MB base64 payloads passed between n8n code nodes choke the runner/broker.
DROP_DIR = '/tmp/spotter_ingest'  # runner-writable (uid 1000)
file_path = ''
if raw_bytes:
    try:
        os.makedirs(DROP_DIR, exist_ok=True)

        # Best-effort cleanup of stale temp files only; do not delete active uploads.
        now = time.time()
        for _old in glob.glob(f'{DROP_DIR}/_ingest_*'):
            try:
                if now - os.path.getmtime(_old) > 3600:
                    os.remove(_old)
            except Exception:
                pass

        safe = ''.join(ch if (ch.isalnum() or ch in '._-') else '_' for ch in (filename or 'upload'))
        file_path = f'{DROP_DIR}/_ingest_{uuid.uuid4().hex}_{safe}'
        _fd = os.open(file_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
        os.write(_fd, raw_bytes)
        os.close(_fd)
    except Exception as _e:
        return _reject(f'temp write failed: {_e}', fmt)

return [{'json': {
    'file_path': file_path,
    'filename': filename,
    'detected_format': fmt,
    'sketch_id': sketch_id,
    'size': len(raw_bytes),
    'context': context,
    'accepted': True,
    # Partially-encrypted archives still parse; route_bytes reports what it
    # skipped. Only a wholly unreadable one is rejected above.
    'errors': ([f'{_enc} of {_total} files in this archive are password-protected '
                f'and were skipped'] if _enc else []),
}}]

meta.notes:
Upload endpoint: POST http://n8n:5678/webhook/upload
Responds immediately (202 Accepted) — import runs in background (~5 min for large ZIPs).
JSON body examples:
  SharpHound ZIP: multipart file upload
  CSV:            {"csv_text": "username,email\njdoe,...", "filename": "users.csv"}
  nmap XML:       {"zip_b64": "<base64-xml>", "filename": "scan.xml"}
  PingCastle:     {"zip_b64": "<base64-xml>", "filename": "ad_hc_corp.local.xml"}
  Nessus CSV:     {"csv_text": "Plugin ID,CVE,Risk,Host,...", "filename": "scan.csv"}
  Plain text:     {"text": "nmap output or paste...", "filename": "paste.txt"}
Check Flowsint graph to verify import completed.
Nessus route requires scripts/register_nessus_type.py --apply; without it the Vulnerability nodes are dropped and hosts/technologies still ingest. On success it fires WF25 (/webhook/vuln-context) to attach exploit availability and roll findings up onto the hosts.
